-- ============================================================================
-- MIGRATION v45: Tarif charter PT. Raja Cepat Nusantara (RACE) 2026
--
-- 1. transport_rate_card.vendor_id dipakai aplikasi sebagai vendors.id, tapi
--    foreign key lamanya menunjuk ke transport_vendor. FK dipindah ke vendors.
-- 2. Tarif dari 3 kesepakatan: 056/MKT_MES/RACE/VII/2026,
--    057/MKT_MES/RACE/IV/2026, 106/MKT_MES/RACE/VII/2026.
--    45 tujuan x 3 unit (GRANDMAX, L300, CDE) = 135 tarif.
-- AMAN dijalankan ulang: tarif hanya ditambah jika rate_code belum ada.
-- ============================================================================

ALTER TABLE public.transport_rate_card
  DROP CONSTRAINT IF EXISTS transport_rate_card_vendor_id_fkey;
ALTER TABLE public.transport_rate_card
  ADD CONSTRAINT transport_rate_card_vendor_id_fkey
    FOREIGN KEY (vendor_id) REFERENCES public.vendors(id) ON DELETE RESTRICT;

